#include <stdio.h>

#define MAXM 5005
#define MAXK 10000

int T[MAXM];
int pos[MAXK + 1];

int main(void) {
    long long N;
    int M;
    if (scanf("%lld", &N) != 1) return 0;
    if (scanf("%d", &M) != 1) return 0;

    for (int i = 0; i < M; i++) {
        scanf("%d", &T[i]);
    }

    long long current_len = N;
    for (int i = 0; i < M; i++) {
        current_len -= current_len / T[i];
    }

    int K = current_len < MAXK ? (int)current_len : MAXK;

    for (int j = 1; j <= K; j++) {
        pos[j] = j;
    }

    for (int i = M - 1; i >= 0; i--) {
        int t_minus_1 = T[i] - 1;
        for (int j = 1; j <= K; j++) {
            pos[j] += (pos[j] - 1) / t_minus_1;
        }
    }

    for (int j = 1; j <= K; j++) {
        printf("%d\n", pos[j]);
    }

    return 0;
}
